//! The `docs/user-guide.md` command index is generated by hand, so it drifts.
//! These tests compare it with the registry: the count, every command name, its
//! MCP tool name, its category label and whether it changes the document.

use hae_exec::{command_list, CommandCategory};

fn guide() -> String {
    std::fs::read_to_string(format!(
        "{}/../../docs/user-guide.md",
        env!("CARGO_MANIFEST_DIR")
    ))
    .expect("docs/user-guide.md must exist")
}

fn category_label(category: CommandCategory) -> &'static str {
    match category {
        CommandCategory::Introspection => "조회(명령)",
        CommandCategory::Lifecycle => "문서 열기·닫기",
        CommandCategory::Query => "조회",
        CommandCategory::Mutation => "편집",
        CommandCategory::History => "이력",
        CommandCategory::Snapshot => "스냅샷·비교",
        CommandCategory::Preview => "미리보기",
        CommandCategory::Persistence => "저장·내보내기",
    }
}

/// `| `command.name` | `mcp_tool_name` | label | yes/no | section |` rows.
fn index_rows(text: &str) -> Vec<Vec<String>> {
    text.lines()
        .filter_map(|line| {
            let cells: Vec<String> = line
                .trim()
                .strip_prefix('|')?
                .strip_suffix('|')?
                .split('|')
                .map(|c| c.trim().trim_matches('`').to_string())
                .collect();
            (cells.len() == 5 && cells[0].contains('.')).then_some(cells)
        })
        .collect()
}

#[test]
fn user_guide_index_matches_the_registry() {
    let text = guide();
    let commands = command_list();

    // 1. The number in the heading and in the sentence above the table.
    let heading = text
        .lines()
        .find(|l| l.starts_with("## 부록."))
        .expect("guide must have an appendix heading");
    assert!(
        heading.contains(&format!("명령 {}개", commands.len())),
        "appendix heading must count {} commands: {heading}",
        commands.len()
    );
    assert!(
        text.contains(&format!("로 얻은 {}개 명령 전체입니다", commands.len())),
        "the appendix sentence must count {} commands",
        commands.len()
    );

    // 2. One row per command, with the same MCP name, category and mutability.
    let rows = index_rows(&text);
    assert_eq!(
        rows.len(),
        commands.len(),
        "the guide index must have one row per registered command"
    );
    for (row, command) in rows.iter().zip(commands.iter()) {
        assert_eq!(row[0], command.name, "row order must follow the registry");
        assert_eq!(row[1], command.mcp_tool_name, "{} MCP name", command.name);
        assert_eq!(
            row[2],
            category_label(command.category),
            "{} category label",
            command.name
        );
        let expected = if command.mutates_content {
            "예"
        } else {
            "아니오"
        };
        assert_eq!(row[3], expected, "{} mutability column", command.name);
    }
}

/// `README.md` states the command count twice (heading and MCP section) and
/// lists the query count; those numbers broke every time a command was added.
#[test]
fn readme_command_counts_match_the_registry() {
    let text = std::fs::read_to_string(format!("{}/../../README.md", env!("CARGO_MANIFEST_DIR")))
        .expect("README.md must exist");
    let commands = command_list();
    assert!(
        text.contains(&format!("명령 {}개", commands.len())),
        "README heading must count {} commands",
        commands.len()
    );
    assert!(
        text.contains(&format!(
            "{}개 명령을 모든 인터페이스가 공유합니다",
            commands.len()
        )),
        "README must count {} shared commands",
        commands.len()
    );
    assert!(
        text.contains(&format!("{}개 명령을 개별 도구", commands.len())),
        "README MCP section must count {} tools",
        commands.len()
    );
    // Every registered command is named somewhere in the README (its group
    // headers are user-facing groupings, not registry categories).
    for command in &commands {
        assert!(
            text.contains(&format!("`{}`", command.name)),
            "README must mention {}",
            command.name
        );
    }
}
